#ifndef BIBO_WORLD_MATERIALTEXTURES_HPP_
#define BIBO_WORLD_MATERIALTEXTURES_HPP_
#include <GL/glew.h>

namespace bibo {
namespace world {
/**
 * Layers of the material textures (the shaders use the same numbers)
 */
enum MaterialLayer {
  kMaterialSnow,
  kMaterialForestFloor,  // moss, soil and fallen needles
  kMaterialDirt,         // the trail with pebbles
  kMaterialRock,         // granite with cracks and lichen
  kMaterialSand,
  kMaterialBark,
  kMaterialNeedles,  // spruce branches
  kMaterialLeaves,
  kMaterialLayerCount
};

/**
 * The PBR materials of the world, generated by the graphics card when the game
 * starts (Shader/material_generator.frag): two texture arrays with a layer per
 * material, one with the color (sRGB) and roughness, the other with the tangent
 * space normal (xy), the height and the ambient occlusion. All of them repeat
 * seamlessly.
 */
class MaterialTextures {
 public:
  /**
   * @param size Width and height of the textures in texels
   */
  explicit MaterialTextures(int size);
  ~MaterialTextures();
  MaterialTextures(const MaterialTextures&) = delete;
  MaterialTextures& operator=(const MaterialTextures&) = delete;

  /**
   * Binds the color and the normal texture array to their texture units
   * (render::TextureUnit)
   */
  void Bind() const;
  GLuint GetAlbedo() const { return albedo_; }
  GLuint GetNormal() const { return normal_; }
  int GetSize() const { return size_; }

 private:
  int size_;
  GLuint albedo_ = 0, normal_ = 0;
};
}  // namespace world
}  // namespace bibo

#endif  // BIBO_WORLD_MATERIALTEXTURES_HPP_
